<section class="glass-panel mt-5 overflow-hidden rounded-2xl"><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-xs"><thead class="bg-white/[.03] text-slate-500"><tr><th class="px-4 py-3">Waktu</th><th class="px-4 py-3">Actor</th><th class="px-4 py-3">Action</th><th class="px-4 py-3">Object</th><th class="px-4 py-3">Hash perubahan</th></tr></thead><tbody class="divide-y divide-white/5"><tr v-for="log in logs.data" :key="log.id"><td class="px-4 py-3 text-slate-400">{{ log.created_at }}</td><td class="px-4 py-3 text-white">{{ log.actor }}</td><td class="px-4 py-3 font-mono text-blue-300">{{ log.action }}</td><td class="px-4 py-3 text-slate-300">{{ log.object_type }} #{{ log.object_id }}</td><td class="max-w-xs truncate px-4 py-3 font-mono text-[9px] text-slate-600">{{ log.after_hash ?? log.before_hash ?? '—' }}</td></tr><tr v-if="!logs.data.length"><td colspan="5" class="p-10 text-center text-slate-500">Belum ada audit log.</td></tr></tbody></table></div><div class="flex flex-wrap gap-1 border-t border-white/10 p-3"><Link v-for="link in logs.links" :key="link.label" :href="link.url ?? '#'" :class="[link.active ? 'bg-blue-600 text-white' : 'bg-white/5 text-slate-400', !link.url ? 'pointer-events-none opacity-40' : '']" class="rounded-lg px-3 py-2 text-xs" v-html="link.label"/></div></section></AuthenticatedLayout></template>
